// Перенос anki_conf/.../CoursesPanel/route/subtitle-counter.ts как есть (план B8a, «Что переносим»).
// =============================================================
// СЧЁТЧИК ПРОСЛУШИВАНИЯ ПО СУБТИТРАМ (контракт обмена, П3-1 · П5-5 · П5-7).
//
// ⚠️ ЕДИНИЦА УЧЁТА — СУБТИТР. «Фраза» на языке владельца это субтитр, а не предложение и не
// окно; полный ролик = каждый субтитр прослушан хотя бы раз (решение владельца 2026-09-08).
//
// ⚠️⚠️ ЗДЕСЬ НЕТ REACT И НЕТ ПЛЕЕРА — ЭТО НЕ СТИЛЬ. Вся арифметика зачёта живёт в одной
// чистой функции `шаг`, потому что её единственный способ проверки — таблица вход/выход.
// Проводка (подписка на время, уровень перемотки, сдвиг) стоит снаружи и проверяется
// отдельно: зелёные тесты чистой функции о проводке не говорят НИЧЕГО.
//
// ⚠️⚠️ ЗАЧЁТ ИДЁТ ПО УРОВНЮ `isSeeking()`, А НЕ ПО ВЕЛИЧИНЕ ШАГА И НЕ ПО СОБЫТИЮ 'seeked'.
// История этой строки стоит трёх абзацев, потому что обе прежние конструкции были СЛОМАНЫ:
//   • ПОРОГ ПО ВЕЛИЧИНЕ не различает ход и перемотку. Прыжок вперёд короче порога приходит
//     как обычный шаг: человек, кликающий по следующей реплике за секунду до конца текущей,
//     получал зачёт КАЖДОЙ фразы, хотя хвост каждой пропущен. Обратная сторона — микро-откат
//     (буферизация, интерполяция шима встроенного плеера) чеканил фантомный повтор.
//   • СОБЫТИЕ 'seeked' зависит от порядка, которого код не даёт: оба транспорта излучают
//     'time' РАНЬШЕ 'seeked' из одного обработчика, а у файлового DOM-событие приходит по
//     ЗАВЕРШЕНИИ перемотки — опрос 250 мс успевает снять прыгнувшее время раньше сигнала.
//   • УРОВЕНЬ `isSeeking()` (transport/types.ts) взводится СИНХРОННО внутри seek(), до
//     присвоения времени, и ловит перемотку, которая вообще не проходит через наш код —
//     системные медиаклавиши, CDP.
//
// ⚠️ СТРАХОВКА ПО ВЕЛИЧИНЕ ОСТАЁТСЯ И НЕ ОТКЛЮЧАЕТСЯ НИКОГДА. Уровень не покрывает скачки
// внутри самого встроенного плеера (главы, реклама): там transport/clock-shim принимает
// скачок вперёд до 2 с молча. Отключаемая страховка была регрессом — после первой же
// перемотки она переставала ловить что бы то ни было.
//
// ⚠️ СДВИГ СУБТИТРОВ ПРИМЕНЯЕТСЯ К ВРЕМЕНИ, ГРАНИЦЫ СЫРЫЕ. Так делает вся панель
// (`adjTime = currentTime - offset` против `c.startTime/c.endTime`; перемотка пишет
// `cue.startTime + offset`). Формула, вычитающая сдвиг по ОБЕ стороны неравенства, его
// сокращает и молча игнорирует — ровно эта ошибка была здесь в редакции 2 спеки.
// =============================================================

/** Реплика дорожки. Границы В СЕКУНДАХ — как их отдаёт плеер (VideoPlayerPanel/types.ts). */
export interface Реплика {
  start: number;
  end: number;
  text: string;
}

export interface СнимокРолика {
  puzzleID: string;
  /** Хэш содержимого дорожки: подмена ловится по текстам и границам (см. `ключСнимка`). */
  ключ: string;
  реплики: Реплика[];
}

export interface Счётчик {
  снимок: СнимокРолика;
  /** Сколько раз конец реплики пересечён ходом воспроизведения. `>= 1` ⇒ «прослушана». */
  услышано: number[];
  /** cᵢ контракта: первое прослушивание = 1, дальше +1 ТОЛЬКО за возврат. */
  возвраты: number[];
  /** `rate_min`: наименьшая ставка, на которой реплику слушали. `0` — не сообщена. */
  минСтавка: number[];
  /** Сколько миллисекунд реплики реально прозвучало (для открытой величины «доля субтитра»). */
  покрытоМс: number[];
  /**
   * Счётчик вёлся с начала ролика и НИ РАЗУ не сбрасывался.
   *
   * ⚠️ ЛОЖЬ ЗДЕСЬ РАЗРУШИТЕЛЬНА, А НЕ ПРОСТО НЕТОЧНА. При `false` отчёт уезжает как
   * `subs_report: "partial"`, и по договорённости с серверной стороной подтверждение
   * («иду дальше») не отправляется вовсе: иначе демон снимет из введённых слова, которые
   * человек слышал ДО сброса. Зачёт ролика при этом не теряется — он держится на доле
   * просмотра, которая от дорожки субтитров не зависит.
   */
  полный: boolean;
  /** Текущий проход начался возвратом (а не перезапуском и не ходом с начала). */
  режимВозврата: boolean;
  /** Последнее наблюдённое время, СО СДВИГОМ. `null` — наблюдений ещё не было. */
  было: number | null;
  /**
   * Реально проигранные отрезки времени (СО СДВИГОМ), слитые, по возрастанию.
   * ⚠️ ЗАЧЕМ (решение владельца 2026-10-05): при смене дорожки посреди ролика «услышано»
   * переносится ПО ВРЕМЕНИ — звук человек слышал, а не текст. Без отрезков перенос
   * пришлось бы делать по старым репликам, и место, где у старой дорожки было пусто, а у
   * новой нашлась речь, считалось бы неуслышанным при полном отчёте.
   */
  проиграно: Array<[number, number]>;
}

/**
 * Страховка: шаг больше этого считается перемоткой, даже если уровень молчит.
 *
 * ⚠️ Та же величина, что уже живёт в `route-clip-events.ts` для прыжка назад. Второго числа
 * не заводим: две константы про одно разъедутся.
 * ⚠️ При скорости ×2 и опросе 250 мс реальный шаг ≈ 0.5 с — запас четырёхкратный.
 */
export const МАКС_ШАГ = 1.5;

/**
 * Реплика, попадание в которую считается ПЕРЕЗАПУСКОМ, а не возвратом.
 *
 * ⚠️ НАЗВАННАЯ СЛЕПАЯ ЗОНА: возврат к самой первой реплике неотличим от перезапуска ролика.
 * Ошибка направлена в безопасную сторону — перезапуск, посчитанный возвратом, обвинил бы
 * материал зря, а мы теряем лишь возвраты к первой фразе. Согласовано с серверной стороной.
 */
const ИНДЕКС_ПЕРЕЗАПУСКА = 0;

/**
 * Ключ снимка дорожки — по СОДЕРЖИМОМУ.
 *
 * ⚠️ ПОЧЕМУ НЕ ПО ЯРЛЫКУ ИСТОЧНИКА И ЧИСЛУ РЕПЛИК. `activeSourceId` — родовой ярлык
 * (`server` / `youtube` / `files`), а `currentSubtitle` на серверном пути ПУСТ ВСЕГДА. Смена
 * языка ютуб-дорожки и перезагрузка серверного набора сохраняют и ярлык, и длину: построчный
 * перевод строится «реплика на каждую строку», поэтому число реплик совпадает систематически.
 * Хэш содержимого ловит подмену по построению и не требует угадывать достаточный набор
 * косвенных признаков.
 */
export function ключСнимка(реплики: Реплика[]): string {
  let h1 = 0x811c9dc5, h2 = 0x01000193;
  const подать = (s: string): void => {
    for (let i = 0; i < s.length; i++) {
      h1 = ((h1 ^ s.charCodeAt(i)) >>> 0) * 16777619 >>> 0;
      h2 = ((h2 + s.charCodeAt(i)) >>> 0) * 2654435761 >>> 0;
    }
  };
  подать(String(реплики.length));
  for (const r of реплики) подать(`␀${r.start}␀${r.end}␀${r.text}`);
  return `${h1.toString(16)}-${h2.toString(16)}-${реплики.length}`;
}

export function завестиСчётчик(снимок: СнимокРолика): Счётчик {
  const n = снимок.реплики.length;
  return {
    снимок,
    услышано: new Array<number>(n).fill(0),
    возвраты: new Array<number>(n).fill(0),
    минСтавка: new Array<number>(n).fill(0),
    покрытоМс: new Array<number>(n).fill(0),
    полный: true,
    режимВозврата: false,
    было: null,
    проиграно: [],
  };
}

export interface Наблюдение {
  /** Текущее время плеера, СЕКУНДЫ, без учёта сдвига. */
  время: number;
  /** Пользовательский сдвиг субтитров, секунды. */
  сдвиг: number;
  /** Уровень транспорта `isSeeking()` — идёт ли перемотка ПРЯМО СЕЙЧАС. */
  идётПеремотка: boolean;
  /** Ставка воспроизведения в этот момент. */
  ставка: number;
}

/**
 * Одно наблюдение времени. Возвращает НОВОЕ состояние (чистая функция).
 *
 * ⚠️ ЗАЧЁТ ПОЛУЧАЕТ РЕПЛИКА, ЧЕЙ КОНЕЦ ПЕРЕСЕЧЁН ХОДОМ. Не вход в реплику: человек,
 * прыгнувший из середины, получил бы её слова даром (решение владельца, правило Р1).
 */
export function шаг(c: Счётчик, o: Наблюдение): Счётчик {
  const стало = o.время - o.сдвиг;

  // Первое наблюдение: якорь, зачёта нет — сравнивать не с чем.
  if (c.было === null) return { ...c, было: стало };

  // ⚠️ УРОВЕНЬ ПЕРВЫМ, ДО ЛЮБОЙ АРИФМЕТИКИ. Пока идёт перемотка, зачёта не бывает; заодно
  // здесь определяется, чем станет следующий проход — возвратом или перезапуском.
  if (o.идётПеремотка) {
    const назад = стало < c.было;
    const врезке = попалВРеплику(c, стало);
    return {
      ...c,
      // Возврат — это движение НАЗАД мимо первой реплики. Прыжок вперёд возвратом не
      // является (это пропуск), попадание в первую реплику — перезапуск.
      режимВозврата: назад && врезке !== ИНДЕКС_ПЕРЕЗАПУСКА,
      было: стало,
    };
  }

  const шагС = стало - c.было;
  if (шагС <= 0) return { ...c, было: стало };
  // Страховка: без сигнала, но шаг неправдоподобен для хода.
  if (шагС > МАКС_ШАГ) return { ...c, было: стало };

  const услышано = c.услышано.slice();
  const возвраты = c.возвраты.slice();
  const минСтавка = c.минСтавка.slice();
  const покрытоМс = c.покрытоМс.slice();

  for (let i = 0; i < c.снимок.реплики.length; i++) {
    const r = c.снимок.реплики[i];
    // Покрытое время: пересечение отрезка хода с отрезком реплики.
    const от = Math.max(c.было, r.start);
    const до = Math.min(стало, r.end);
    if (до > от) покрытоМс[i] += Math.round((до - от) * 1000);

    // Зачёт: конец реплики пересечён ЭТИМ шагом.
    if (c.было < r.end && r.end <= стало) {
      услышано[i] += 1;
      // cᵢ: первое прослушивание = 1; дальше растёт ТОЛЬКО за возврат.
      if (услышано[i] === 1) возвраты[i] = 1;
      else if (c.режимВозврата) возвраты[i] += 1;

      if (o.ставка > 0) {
        минСтавка[i] = минСтавка[i] === 0 ? o.ставка : Math.min(минСтавка[i], o.ставка);
      }
    }
  }

  return { ...c, услышано, возвраты, минСтавка, покрытоМс, было: стало,
    проиграно: добавитьОтрезок(c.проиграно ?? [], c.было, стало) };
}

/** Влить отрезок [от, до] в слитый список отрезков (чистая функция). */
function добавитьОтрезок(список: Array<[number, number]>, от: number, до: number): Array<[number, number]> {
  const все = [...список, [от, до] as [number, number]].sort((a, b) => a[0] - b[0]);
  const out: Array<[number, number]> = [];
  for (const [a, b] of все) {
    const last = out[out.length - 1];
    if (last && a <= last[1] + 1e-6) last[1] = Math.max(last[1], b);
    else out.push([a, b]);
  }
  return out;
}

/**
 * Маркеры не-речи — ТЕ ЖЕ, что знает демон (MarkerLemmaIDs: route_v2.go, «[Music]/[foreign]/
 * [Applause]/[Laughter]/[Inaudible]»). ⚠️ Список должен совпадать с демоном: расхождение
 * означало бы, что ролик «прослушан» у клиента по одному правилу, а слова снимаются по другому.
 */
const МАРКЕРЫ_НЕ_РЕЧИ = new Set([
  'music', 'foreign', 'applause', 'laughter', 'inaudible', 'cheering', 'snort', 'clears',
]);

/**
 * Шумовая реплика — без текста в квадратных/круглых скобках и без символов в ней не остаётся
 * ни одного слова, кроме маркеров не-речи (`[Music]`, `♪ ♪`, `music ♪`). В признак «ролик
 * прослушан» такие реплики не входят: человек вправе не слушать музыку (решение владельца
 * 2026-10-05). `[Music] you` — НЕ шумовая: в ней есть слово.
 */
export function шумоваяРеплика(текст: string): boolean {
  const без = (текст || '').replace(/\[[^\]]*\]|\([^)]*\)/g, ' ');
  const слова = без.toLowerCase().split(/[^\p{L}'-]+/u).filter((w) => /\p{L}/u.test(w));
  return слова.every((w) => МАРКЕРЫ_НЕ_РЕЧИ.has(w));
}

/**
 * Ролик прослушан ПО СУБТИТРАМ: услышаны все нешумовые реплики (решение владельца 2026-10-05).
 * Нешумовых нет — `false`: по субтитрам решать нечего, решает конец ролика (вызывающий).
 */
export function прослушанВесь(c: Счётчик): boolean {
  let есть = false;
  for (let i = 0; i < c.снимок.реплики.length; i++) {
    if (шумоваяРеплика(c.снимок.реплики[i].text)) continue;
    есть = true;
    if (!(c.услышано[i] >= 1)) return false;
  }
  return есть;
}

/**
 * Перенести счёт на ДРУГУЮ дорожку того же ролика ПО ВРЕМЕНИ (решение владельца 2026-10-05).
 * Реплика новой дорожки услышана, если её КОНЕЦ пройден непрерывным ходом — то же правило, что
 * у шага (Р1: зачёт по пересечению конца ходом; вошедший в середину и прошедший конец — услышал).
 * Аудит 2026-10-05 (MED-3): прежнее «весь отрезок проигран» было строже шага и при полном
 * отчёте занижало услышанное.
 * ⚠️ Полнота сохраняется: проигранные отрезки ведутся с начала ролика и от дорожки не
 * зависят — сброс (`сбросить`) терял бы всё услышанное до смены и делал отчёт `partial`.
 * Ставка при переносе не известна (0 — «не сообщена»), возвраты — 1 у услышанных.
 */
export function перенестиПоВремени(c: Счётчик, снимок: СнимокРолика): Счётчик {
  const отрезки = c.проиграно ?? [];
  const n = снимок.реплики.length;
  const услышано = new Array<number>(n).fill(0);
  const покрытоМс = new Array<number>(n).fill(0);
  снимок.реплики.forEach((r, i) => {
    if (отрезки.some(([a, b]) => a < r.end && r.end <= b)) услышано[i] = 1;
    for (const [a, b] of отрезки) {
      const x = Math.max(a, r.start), y = Math.min(b, r.end);
      if (y > x) покрытоМс[i] += Math.round((y - x) * 1000);
    }
  });
  return {
    ...c, снимок, услышано, покрытоМс,
    возвраты: услышано.slice(),
    минСтавка: new Array<number>(n).fill(0),
  };
}

/** Индекс реплики, внутри которой лежит время, либо -1. */
function попалВРеплику(c: Счётчик, t: number): number {
  for (let i = 0; i < c.снимок.реплики.length; i++) {
    const r = c.снимок.реплики[i];
    if (t >= r.start && t < r.end) return i;
  }
  // ⚠️ Время ДО первой реплики (пауза перед речью) — это тоже перезапуск, а не возврат.
  return c.снимок.реплики.length > 0 && t < c.снимок.реплики[0].start
    ? ИНДЕКС_ПЕРЕЗАПУСКА
    : -1;
}

/** Сброс: заводим заново на новом снимке. `полный` гаснет НАВСЕГДА до смены ролика. */
export function сбросить(снимок: СнимокРолика): Счётчик {
  return { ...завестиСчётчик(снимок), полный: false };
}

/**
 * Перенести счёт на новый снимок ТОЙ ЖЕ дорожки. `null` — дорожка другая, нужен `сбросить`.
 *
 * ⚠️⚠️ ПРИХОД ДЛИТЕЛЬНОСТИ — НЕ СМЕНА ДОРОЖКИ (владелец 2026-10-05: «так не должно быть»).
 * Субтитры могут приехать раньше метаданных; когда длительность становится известна, хвост
 * подрезается: у последних реплик меняется конец, а начавшиеся за концом носителя выпадают.
 * Ключ снимка от этого меняется, и прежде счётчик сбрасывался ⇒ `полный=false` навсегда ⇒
 * отчёт `partial` ⇒ демон не разбирал ролик вовсе (clipStumbles требует `full`), включая
 * отметки «не расслышал».
 * ⚠️ ПРИЗНАК ТОЙ ЖЕ ДОРОЖКИ: на общей длине совпадают НАЧАЛО и ТЕКСТ каждой реплики. Концы
 * сравнивать нельзя — их и меняет подрезка. Разница в длине допустима только хвостом: адреса
 * `String(i)` общих реплик при этом не сдвигаются, а выпавшие/добавленные лежат за концом
 * носителя, то есть до прихода длительности прозвучать не могли.
 */
export function перенестиНаСнимок(c: Счётчик, снимок: СнимокРолика): Счётчик | null {
  if (c.снимок.puzzleID !== снимок.puzzleID) return null;
  const было = c.снимок.реплики, стало = снимок.реплики;
  const общая = Math.min(было.length, стало.length);
  if (общая === 0) return null;
  // ⚠️ РОСТ — ТОЛЬКО ПОКА НИЧЕГО НЕ УСЛЫШАНО И ПОЗИЦИЯ РАНЬШЕ ДОБАВЛЕННОГО (аудит 2026-10-05,
  // MED-8). Добавленные реплики могли уже прозвучать, пока их не было в снимке; нулевой счёт
  // у них при `полный=true` объявил бы их неуслышанными. Усадка безопасна: выпадают только
  // реплики за концом носителя.
  if (стало.length > было.length
      && (c.услышано.some((n) => n > 0) || (c.было ?? 0) >= стало[было.length].start)) return null;
  for (let i = 0; i < общая; i++) {
    if (было[i].start !== стало[i].start || было[i].text !== стало[i].text) return null;
  }
  const n = стало.length;
  const подогнать = (a: number[]): number[] =>
    a.length >= n ? a.slice(0, n) : [...a, ...new Array<number>(n - a.length).fill(0)];
  return {
    ...c,
    снимок,
    услышано: подогнать(c.услышано),
    возвраты: подогнать(c.возвраты),
    минСтавка: подогнать(c.минСтавка),
    покрытоМс: подогнать(c.покрытоМс),
  };
}

// ── УПАКОВКА В ОТЧЁТ О РОЛИКЕ (контракт обмена, П3-1 · П3-2) ──────────────────

/**
 * Разбиение реплики на слова.
 *
 * ⚠️ ЕДИНСТВЕННАЯ КОПИЯ ПРАВИЛА. Оно жило встроенным в `route-clip-events.ts` («переслушал
 * место»); вторая копия разъехалась бы молча, а слова — это то, по чему демон резолвит
 * леммы. Правило плохое — правится здесь и сразу для обоих потребителей.
 */
export function словаРеплики(текст: string): string[] {
  return текст.toLowerCase().split(/[^a-zà-ÿ'-]+/i).filter((w) => w.length > 1);
}

/**
 * Полнота отчёта — П3-2: «полнота НАЗЫВАЕТСЯ, а не угадывается».
 *
 * ⚠️ ТРИ СОСТОЯНИЯ ВЫГЛЯДЯТ ОДИНАКОВО (пустые массивы), А ПОСЛЕДСТВИЯ У НИХ ПРОТИВОПОЛОЖНЫЕ.
 * Поэтому пометка обязательна, а её отсутствие при непустых массивах демон отвергает.
 */
export type ПолнотаОтчёта = '' | 'full' | 'absent' | 'partial';

export interface УслышанныйСубтитр {
  sub_ref: string; from_ms: number; to_ms: number;
  rate_min: number; count: number; lemmas: string[];
}
export interface НеуслышанныйСубтитр {
  sub_ref: string; from_ms: number; to_ms: number; lemmas: string[];
}
export interface ОтчётРолика {
  subs_report: ПолнотаОтчёта;
  subs_heard: УслышанныйСубтитр[];
  subs_unheard: НеуслышанныйСубтитр[];
}

const мс = (сек: number): number => Math.max(0, Math.round(сек * 1000));

/**
 * Собрать отчёт о ролике из счётчика.
 *
 * @param c — счётчик, либо `null`, если счёт не вёлся.
 * @param наборРазрешён — знаем ли мы ОКОНЧАТЕЛЬНО, что дорожка либо приехала, либо её нет.
 *   ⚠️ Без этого признака пустой список реплик неотличим от «набор ещё едет», и ролик был бы
 *   объявлен пройденным на первом же кадре — у КАЖДОГО ролика.
 *
 * ⚠️ `sub_ref` — МЕСТНЫЙ адрес и ОДИН СЛОВАРЬ НА ОБА МАССИВА: повторный адрес демон отвергает,
 * потому что субтитр, попавший в оба, раздул бы знаменатель.
 * ⚠️ Границы уезжают КАК ЕСТЬ. Перекрытия не схлопываем: автоматические дорожки YouTube —
 * скользящие окна и перекрываются по построению, а объединение отрезков считает демон.
 * Схлопнув их здесь, мы отняли бы у него данные, из которых он это делает.
 */
export function собратьОтчёт(c: Счётчик | null, наборРазрешён: boolean): ОтчётРолика {
  if (!c) {
    // Счёта не было. Единственное, что мы вправе утверждать, — «субтитров нет вовсе», и
    // только когда это ОКОНЧАТЕЛЬНО известно.
    return { subs_report: наборРазрешён ? 'absent' : '', subs_heard: [], subs_unheard: [] };
  }
  const heard: УслышанныйСубтитр[] = [];
  const unheard: НеуслышанныйСубтитр[] = [];
  c.снимок.реплики.forEach((r, i) => {
    const общее = { sub_ref: String(i), from_ms: мс(r.start), to_ms: мс(r.end) };
    const lemmas = словаРеплики(r.text);
    if (c.услышано[i] >= 1) {
      heard.push({ ...общее, rate_min: c.минСтавка[i], count: c.возвраты[i], lemmas });
    } else {
      unheard.push({ ...общее, lemmas });
    }
  });
  // ⚠️⚠️ НИ ОДНОЙ УСЛЫШАННОЙ РЕПЛИКИ — ЭТО «НЕ НАЧИНАЛ», А НЕ «СЛУШАЛ И НЕ РАЗОБРАЛ».
  // Найдено ЖИВЫМ прогоном 2026-09-11: ролик, открытый автостартом на доли секунды, отдавал
  // `subs_report: "full"` с пустым `subs_heard` и полным `subs_unheard` (49 субтитров), а
  // `played_frac` при `full` не едет вовсе.
  // ЦЕНА У ДЕМОНА (route_snapshot_events.go:1210-1238, сверено серверной стороной):
  // `recordUnheardIntroduced` при `full` помечает неуслышанными все слова `c.Introduced`,
  // которых нет в `heard`. Пустой `heard` ⇒ помечаются ВСЕ вводимые слова клипа (до 17 на
  // клип), и назад такое слово НЕ ВОЗВРАЩАЕТСЯ.
  // ⚠️ РАЗЛИЧЕНИЕ, НА КОТОРОМ ВСЁ ДЕРЖИТСЯ: `услышано` растёт по ПЕРЕСЕЧЕНИЮ КОНЦА РЕПЛИКИ
  // ходом воспроизведения, а не по пониманию. Значит «ни одной» не может означать «слушал и
  // не разобрал» — только «не начинал». Утверждать состав в этом случае мы не вправе.
  // ⚠️ ЧТО ЕДЕТ ВМЕСТО: пустая пометка ⇒ поля на проводе нет ⇒ уезжает `played_frac`, и
  // зачёт идёт по доле просмотра. Сторона безопасная: доля мала, порог демона не взят,
  // слова не снимаются.
  // ⚠️ И ЭТО НЕ `absent`. `absent` значит «субтитров у ролика НЕТ» и разрешает зачитывать по
  // доле не глядя; здесь субтитры ЕСТЬ, и мы просто ничего про них не утверждаем.
  // ⚠️ НАЗВАННЫЙ КРАЙ (от серверной стороны): ролик КОРОЧЕ одной реплики даёт пустой
  // `услышано` ЗАКОННО. Правило и там ведёт себя верно, но случай другой — совпадение
  // поведения не делает его доказательством.
  if (heard.length === 0) {
    return { subs_report: '', subs_heard: [], subs_unheard: [] };
  }

  // ⚠️⚠️ ДОРОЖКА НЕ В НАШЕМ АЛФАВИТЕ ⇒ ОТЧЁТ НЕПОЛНЫЙ, И ЭТО НЕ ПРИДИРКА.
  // Правило разбиения на слова оставляет только латиницу (корпус английский). Если человек
  // выбрал основной дорожкой русскую, `lemmas` пусты У КАЖДОГО субтитра — и молчание тут
  // ОПАСНО: демон исключает из счёта спотыкания субтитры, несущие вводимые слова, а не сумев
  // их опознать, оставит ВСЕ ⇒ спотыкание выйдет ЗАВЫШЕННЫМ ⇒ он предложит сбавить темп
  // человеку, который открыл субтитры по нашей же просьбе. Это ровно тот перекос, который
  // контракт объявляет недопустимым: «механизм систематически врёт в сторону „ему тяжело“».
  // ⇒ Помечаем отчёт как неполный. Нового поля не заводим: `partial` уже значит «отчёту
  // нельзя верить как полному рассказу», и его последствия ровно те, что нужны — зачёт по
  // доле просмотра, спотыкание не считается, слова из введённых не снимаются.
  // ⚠️ На маршруте случай не возникает: там дорожка приезжает набором, и `cues` строятся из
  // `text_en` ПО ПОСТРОЕНИЮ (useSubtitles: `lines.map(l => l.text_en)`), а перевод живёт
  // отдельным массивом. Случай живёт только на файловом пути, где человек сам выбрал файл.
  // ⚠️⚠️ ЭТО РАЗМЕН, А НЕ ИЗМЕРЕНИЕ — И ЦЕНУ ДЕРЖИМ НАЗВАННОЙ. В этом случае разделение
  // «слышал / не слышал» ДОСТОВЕРНО: сброса не было, состав полон, отсутствуют только слова.
  // То есть доля по массивам здесь была бы ТОЧНЕЕ доли просмотра, и мы сознательно ею не
  // пользуемся — не завышать спотыкание важнее точности доли. Без этой записи следующий
  // читатель увидит `partial` и решит, что доля недостоверна ПО ЗАМЕРУ, а она недостоверной
  // не измерялась.
  //
  // ⚠️ И ЗАПРЕТ НА БУДУЩЕЕ (в контракте у серверной стороны стоит явно): у `partial` теперь
  // ДВЕ причины — сброс счётчика и чужой алфавит, — и различать их не нужно, последствия
  // совпадают. Но выводить причину ИЗ ФОРМЫ ДАННЫХ («слова пусты ⇒ значит вторая») НЕЛЬЗЯ:
  // это ровно то угадывание, ради запрета которого полнота НАЗЫВАЕТСЯ, а не распознаётся.
  // Понадобится различать — заведём второй причине собственное имя.
  const естьСлова = heard.some((x) => x.lemmas.length > 0)
    || unheard.some((x) => x.lemmas.length > 0);
  const полный = c.полный && естьСлова;
  return { subs_report: полный ? 'full' : 'partial', subs_heard: heard, subs_unheard: unheard };
}
